<?php
declare(strict_types=1);
require dirname(__DIR__).'/src/Sales/OfficeSalesSchema.php';
require dirname(__DIR__).'/src/Sales/OfficeSalesService.php';
require dirname(__DIR__).'/src/Sales/OfficeSalesPdf.php';
require dirname(__DIR__).'/src/Sales/OfficeSalesView.php';
use Brebo\Office\Sales\OfficeSalesBilling as Billing;
use Brebo\Office\Sales\OfficeSalesService as Sales;
use Brebo\Office\Sales\OfficeSalesSchema;
use Brebo\Office\Sales\OfficeSalesPdf;
use Brebo\Office\Sales\OfficeSalesView;
set_error_handler(static function(int $severity,string $message): never {throw new RuntimeException($message);});
function billingCheck(bool $ok,string $message): void {if(!$ok)throw new RuntimeException($message);}
function billingDenied(callable $f): void {try{$f();}catch(DomainException|InvalidArgumentException $e){return;}throw new RuntimeException('Expected rejection');}
function billingLine(string $price,string $vat='21',string $quantity='1'): array {return ['description'=>'Werkzaamheden','quantity'=>$quantity,'price'=>$price,'vat'=>$vat];}
$t=Sales::totals([billingLine('121.00'),billingLine('109.00','9'),billingLine('50.00','0')],'incl');
billingCheck($t['net_cents']===25000&&$t['vat_cents']===3000&&$t['gross_cents']===28000,'Mixed inclusive rates reconcile');
billingCheck(count(Billing::taxes($t['lines']))===3,'Separate VAT subtotals');
$t=Sales::totals([billingLine('19.95','21','12')],'incl');billingCheck($t['gross_cents']===23940&&$t['net_cents']===19785&&$t['vat_cents']===4155,'Inclusive calculation rounds the extended line');
$t=Sales::totals([billingLine('100','21','1.125')],'incl');billingCheck($t['gross_cents']===11250&&$t['net_cents']===9298&&$t['vat_cents']===1952,'Fractional quantities inclusive');
$a=Billing::allocation(['labor_amount'=>'600','g_percent'=>'25'],100000,121000);billingCheck($a['g_cents']===15000&&$a['ordinary_cents']===106000,'G account percentage uses labor, not invoice total');
billingDenied(fn()=>Billing::allocation(['labor_amount'=>'1001','g_percent'=>'25'],100000,121000));billingDenied(fn()=>Billing::allocation(['g_percent'=>'25'],100000,121000));billingDenied(fn()=>Billing::allocation(['labor_amount'=>'600','g_percent'=>'101'],100000,121000));billingDenied(fn()=>Billing::allocation(['labor_amount'=>'600','g_percent'=>'25','g_iban'=>'NL19ABNA0894351567'],100000,121000));
billingCheck(Billing::validGiban('NL91ABNA0417164300'),'IBAN checksum example');
$db=new PDO('sqlite::memory:',null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);foreach(OfficeSalesSchema::statements(true) as $sql)$db->exec($sql);
$db->exec("CREATE TABLE office_operator_accounts(id INTEGER PRIMARY KEY,active INTEGER);INSERT INTO office_operator_accounts VALUES(1,1),(2,1);
CREATE TABLE office_module_permissions(operator_id INTEGER,module TEXT,permission TEXT);INSERT INTO office_module_permissions VALUES(1,'finance','read'),(1,'finance','draft_edit'),(2,'finance','read'),(2,'finance','draft_edit');
CREATE TABLE office_projects(id INTEGER PRIMARY KEY,title TEXT);INSERT INTO office_projects VALUES(10,'Project A'),(20,'Project B');
CREATE TABLE office_project_memberships(operator_id INTEGER,project_id INTEGER,permission TEXT);INSERT INTO office_project_memberships VALUES(1,10,'read'),(2,20,'read');
CREATE TABLE office_crm_relations(id INTEGER PRIMARY KEY,display_name TEXT,legal_name TEXT,email TEXT,street TEXT,postal_code TEXT,city TEXT,country_code TEXT,vat_number TEXT,status TEXT);INSERT INTO office_crm_relations VALUES(4,'Voorbeeld','Voorbeeld B.V.','test@example.com','Voorbeeldstraat 1','1234 AB','Voorbeeldstad','NL','','active');
CREATE TABLE office_crm_external_identities(relation_id INTEGER,provider_code TEXT,external_id TEXT);INSERT INTO office_crm_external_identities VALUES(4,'moneybird','42');
CREATE TABLE office_project_contracts(id INTEGER PRIMARY KEY,office_project_id INTEGER,contract_number TEXT,contract_amount TEXT,currency TEXT,status TEXT);INSERT INTO office_project_contracts VALUES(100,10,'C-100','10000.00','EUR','signed'),(200,20,'C-200','5000.00','EUR','signed');
CREATE TABLE office_project_terms(id INTEGER PRIMARY KEY,contract_id INTEGER,term_number INTEGER,description TEXT,percentage TEXT,amount TEXT,status TEXT,due_date TEXT);INSERT INTO office_project_terms VALUES(101,100,1,'Eerste termijn','20.0000','2000.00','planned','2026-11-21'),(102,100,2,'Tweede termijn','30.0000','3000.00','planned','2026-12-21'),(103,100,3,'Slottermijn','50.0000','5000.00','planned','2026-12-31'),(201,200,1,'Ander project','100.0000','5000.00','planned','2026-11-21');");
$one=new Sales($db,'1');$two=new Sales($db,'2');billingCheck(count($one->termChoices())===3,'Only authorized unclaimed terms');billingDenied(fn()=>$one->sourceTerm(201));
$draft=$one->termDraft(101,'2026-11-07');billingCheck($draft['net_cents']===200000&&$draft['term_percent_units']===200000,'Term uses contract percentage');
$input=['relation_id'=>4,'office_project_id'=>10,'source_term_id'=>101,'term_percent'=>'20','price_mode'=>'excl','invoice_date'=>'2026-11-07','due_date'=>'2026-11-21','reference'=>'C-100','lines'=>json_decode($draft['lines_json'],true),'labor_amount'=>'800','g_percent'=>'25','g_iban'=>''];
$id=$one->save($input);$row=$one->get($id);billingCheck((int)$row['g_cents']===20000&&(int)$row['labor_cents']===80000,'Allocation persisted in separate context');
billingDenied(fn()=>$one->prepare($id,1,'invoice','test@example.com','Test',['21'=>'1'],'2026-11-07'));
$input['g_iban']='NL91ABNA0417164300';$one->save($input,$id,1);$delivery=$one->prepare($id,2,'invoice','test@example.com','Test',['21'=>'1'],'2026-11-07');
$command=json_decode($db->query('SELECT payload_json FROM office_finance_sales_delivery WHERE id='.$delivery)->fetchColumn(),true);billingCheck(str_contains($command['sales_invoice']['payment_conditions'],'200.00'),'G payment split is frozen in the outgoing command');
$one->dispatch($delivery,static fn()=>['status'=>'ok','sales_invoice'=>['id'=>'9001','invoice_id'=>'TEST-1','contact_id'=>'42','workflow_id'=>'1','document_style_id'=>'2','identity_id'=>'3','sent_at'=>'2026-11-07T12:00:00Z','state'=>'open']],'2026-11-07');
$row=$one->get($id);$one->recordReceipt($id,(int)$row['revision'],'500.00','2026-11-07','TEST-PAYMENT','2026-11-07');
$second=$one->termDraft(102,'2026-11-07');$input2=$input;$input2['source_term_id']=102;$input2['term_percent']='25';$input2['lines']=[billingLine('2500.00')];$input2['labor_amount']='1000';$id2=$one->save($input2);$row2=$one->get($id2);$summary=json_decode($row2['summary_json'],true);
billingCheck((int)$row2['net_cents']===250000&&$summary['previous_net_cents']===200000&&$summary['paid_gross_cents']===50000&&$summary['due_including_current_gross_cents']===494500&&$summary['unbilled_after_net_cents']===550000,'Contract summary separates actual paid, current due and unbilled net');
billingCheck($db->query('SELECT amount FROM office_project_terms WHERE id=102')->fetchColumn()==='3000.00','Original term plan preserved');
$before=(int)$db->query('SELECT COUNT(*) FROM office_finance_sales_invoice')->fetchColumn();billingDenied(fn()=>$one->save($input));billingCheck((int)$db->query('SELECT COUNT(*) FROM office_finance_sales_invoice')->fetchColumn()===$before,'Duplicate term rolls back invoice and metadata');
$over=$input2;$over['source_term_id']=103;$over['term_percent']='80';$over['lines']=[billingLine('8000.00')];billingDenied(fn()=>$one->save($over));
$wrong=$input2;$wrong['office_project_id']=20;billingDenied(fn()=>$one->save($wrong));billingDenied(fn()=>$two->get($id2));
$manual=$input2;$manual['office_project_id']='';$manual['source_term_id']=0;$manual['price_mode']='incl';$manual['lines']=[billingLine('121.00')];$manual['labor_amount']='';$manual['g_percent']='';$manual['g_iban']='';$mid=$one->save($manual);$m=$one->get($mid);billingCheck($m['price_mode']==='incl'&&(int)$m['net_cents']===10000,'Inclusive mode persists');
$d=$one->prepare($mid,1,'invoice','test@example.com','Test',['21'=>'1'],'2026-11-07');$c=json_decode($db->query('SELECT payload_json FROM office_finance_sales_delivery WHERE id='.$d)->fetchColumn(),true);billingCheck($c['sales_invoice']['prices_are_incl_tax']===true&&$c['sales_invoice']['details_attributes'][0]['price']==='121.00','Original inclusive price is sent without lossy unit conversion');
$html=OfficeSalesView::render([],$row2,$one->customers(),$one->projects(),[],'csrf',true,false,'2026-11-07');billingCheck(str_contains($html,'Aanneemsom en termijnen')&&str_contains($html,'5.500,00'),'Contract summary only for linked terms');
$plain=OfficeSalesView::render([],$m,$one->customers(),$one->projects(),[],'csrf',true,false,'2026-11-07');billingCheck(!str_contains($plain,'<h3>Aanneemsom en termijnen</h3>'),'Standalone invoice has no inferred contract summary');
$pdf=OfficeSalesPdf::render($row2);billingCheck(str_contains($pdf,'Aanneemsom en termijnen')&&str_contains($pdf,'Naar G-rekening'),'PDF contains own contract and G split snapshots');
$db->exec("UPDATE office_project_terms SET description='Gewijzigde bron' WHERE id=102");billingDenied(fn()=>$one->prepare($id2,1,'invoice','test@example.com','Test',['21'=>'1'],'2026-11-07'));billingCheck($one->get($id2)['status']==='draft','Changed source blocks send before provider call');
if(($argv[1]??'')==='--fixture')file_put_contents($argv[2],OfficeSalesView::render([],$row2,$one->customers(),$one->projects(),[],'csrf',true,false,'2026-11-07','',false,false,[],'nonce'));
if(($argv[1]??'')==='--sample')file_put_contents($argv[2],$pdf);
echo "OFFICE_SALES_BILLING_OK\n";
